def weather_summary(summary: str | None, language: str | None) -> str:
    locale = locale_key(language)
    value = (summary or "").lower()
    key = "unknown"
    if "thunder" in value or "storm" in value:
        key = "storms"
    elif "shower" in value or "drizzle" in value:
        key = "showers"
    elif "rain" in value:
        key = "rain"
    elif "clear" in value:
        key = "clear"
    elif "cloud" in value or "overcast" in value:
        key = "cloudy"
    elif "fog" in value:
        key = "fog"
    elif "snow" in value:
        key = "snow"
    return SUMMARY_TERMS[locale][key]


def locale_key(language: str | None) -> str:
    key = (language or "en").replace("_", "-").split("-", 1)[0].lower()
    return key if key in SUPPORTED else "en"


def text(key: str, language: str | None) -> str:
    locale = locale_key(language)
    return TEXT.get(locale, TEXT["en"]).get(key, TEXT["en"][key])


