def crop_names(crops: list[str] | tuple[str, ...], language: str | None) -> str:
    names = CROP_NAMES[locale_key(language)]
    return ", ".join(names.get(crop.casefold(), crop) for crop in crops)


def weather_answer(place: str, day: str, chance: int | None, summary: str | None, temperature: float | None, language: str | None) -> str:
    locale = locale_key(language)
    if chance is None:
        return WEATHER_UNAVAILABLE[locale]
    temp = f"; {temperature}°C" if temperature is not None else ""
    sky = weather_summary(summary, locale)
    day_text = DAY_LABELS[locale].get(day, day)
    return WEATHER_REPLY[locale].format(place=place, day=day_text, chance=f"{chance}%", summary=sky, temperature=temp)
